<script setup>
import {ref,onUnmounted} from 'vue';import axios from 'axios';
const props=defineProps({url:String,saved:Boolean,disabled:Boolean});const emit=defineEmits(['saved','busy']);
const recording=ref(false),uploading=ref(false),error=ref(''),version=ref(0);let recorder,stream,disposed=false;
async function upload(file){if(!file)return;if(file.size>20*1024*1024){error.value='Tệp âm thanh tối đa 20 MB.';return;}uploading.value=true;emit('busy',true);error.value='';const data=new FormData();data.append('recording',file);try{await axios.post(props.url,data,{timeout:120000});version.value++;emit('saved');}catch(failure){error.value=Object.values(failure.response?.data?.errors||{}).flat().join(' · ')||'Chưa tải được âm thanh. Kiểm tra dung lượng tệp và kết nối rồi thử lại.';}finally{uploading.value=false;emit('busy',false);}}
async function start(){error.value='';try{stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm','audio/ogg','audio/mp4'].find(type=>MediaRecorder.isTypeSupported(type));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:{});const chunks=[];recorder.ondataavailable=event=>{if(event.data.size)chunks.push(event.data);};recorder.onstop=()=>{stream.getTracks().forEach(track=>track.stop());recording.value=false;emit('busy',false);if(!disposed){const blob=new Blob(chunks,{type:recorder.mimeType});const extension=recorder.mimeType.includes('mp4')?'mp4':recorder.mimeType.includes('ogg')?'ogg':'webm';upload(new File([blob],'recording.'+extension,{type:blob.type}));}};recorder.start();recording.value=true;emit('busy',true);}catch{error.value='Chưa truy cập được micro. Cho phép micro trong trình duyệt hoặc chọn tệp âm thanh.';}}
function stop(){if(recorder?.state==='recording')recorder.stop();}
onUnmounted(()=>{disposed=true;stop();stream?.getTracks().forEach(track=>track.stop());emit('busy',false);});
</script>
<template><div class="recording-controls"><button v-if="!recording" type="button" class="secondary" :disabled="disabled||uploading" @click="start">Ghi âm bằng micro</button><button v-else type="button" @click="stop">Dừng & lưu ghi âm</button><span v-if="recording" class="time-warning" role="status">Đang ghi âm…</span><label v-else>Hoặc chọn tệp âm thanh<input type="file" accept="audio/*,.webm" :disabled="disabled||uploading" @change="event=>upload(event.target.files[0])"/></label><span v-if="uploading" role="status">Đang tải bài nói…</span><audio v-if="saved&&!uploading" :key="version" :src="url+'?v='+version" controls/><p v-if="error" class="error" role="alert">{{error}}</p></div></template>
